import sys
with open('vllm/attention/ops/triton_unified_attention.py', 'r') as f:
    lines = f.readlines()
# find start and end indices
start = None
for i, line in enumerate(lines):
    if line.strip().startswith('@triton.jit') and i+1 < len(lines) and lines[i+1].strip().startswith('def kernel_unified_attention_2d'):
        start = i
        break
if start is None:
    print("Function not found")
    sys.exit(1)
# find the end of function (next function definition or end of file)
def_count = 0
end = None
for i in range(start, len(lines)):
    if lines[i].strip().startswith('def '):
        def_count += 1
    if def_count == 2:
        end = i
        break
if end is None:
    end = len(lines)
function_lines = lines[start:end]
print(''.join(function_lines))
EOF"}

