{"command": "python3 -c "
import json, sys
with open('/prediction.json') as f:
    data = json.load(f)
if not isinstance(data, dict):
    print('ERROR: root is not dict')
    sys.exit(1)
for file_path, funcs in data.items():
    if not isinstance(funcs, dict):
        print('ERROR: inner not dict')
        sys.exit(1)
    for func_name, body in funcs.items():
        if not isinstance(body, str):
            print('ERROR: body not string')
            sys.exit(1)
        # ensure body starts with '@triton.jit'
        if not body.strip().startswith('@triton.jit'):
            print('WARNING: function body missing decorator')
        # ensure function name appears
        if func_name not in body:
            print('WARNING: function name not in body')
print('Validation passed')
" 2>&1"}

